fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n < 2 {
        return numbers;
    }

    // The resulting vector length is 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    // Iterate over the numbers except the last one
    for i in 0..(n - 1) {
        result.push(numbers[i]);
        result.push(delimiter);
    }
    // Push the last element without delimiter after it
    result.push(numbers[n - 1]);

    result
}